import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch BN stories: the same defendant, back in this court.
extension FollowUpCases {
    static let batchBN: [CaseTemplate] = [pickupLineThreatsBack, shoulderPassBack, closedStoreLotBack, flowersNoteBack, mysteryBoxBack, stolenTruckReportBack, soccerSidelineBack, cabinClaimBack, jobsiteToolboxBack, waistbandGunBack, gradePortalBack, boatRampDwiBack]

    static let pickupLineThreatsBack = SmallCases.make(
        key: "story.followup.pickupLineThreatsBack",
        category: .violent,
        headlines: ["Parent Threatens Teacher in School Pickup Line", "Defendant From Babysitter Case Back Over Words at a School Fence"],
        law: "communicatingThreats",
        spec: "Willfully threatened {V} to inflict physical injury, on {DATE}.",
        ages: 25...55,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} became upset when {V}, a teacher's aide, would not release a child to {DL} at an elementary school pickup line on {DATE}. A coworker heard {DL} say, 'You'll regret this when I see you off school grounds.' {DL} says {D.he} was only frustrated.",
        state: [E(.statement, 3, "Coworker", "Heard the threat at the fence."), E(.digital, 2, "School Call Log", "{D} called the office twice that afternoon.")],
        defense: [E(.statement, 1, "Frustration", "{DL} says it was a figure of speech.")],
        role: "Teacher's aide",
        exam: [.direct("What is your job at the elementary school?", "\"I am a teacher's aide, and one of my duties is working the afternoon pickup line, where I check each child against the approved pickup list before I release them to anyone.\""),
               .direct("What happened at the pickup line that afternoon?", "\"{DL} came to the fence and asked for a child. The name was not on the approved list, so I told {D.him} I could not release the child and sent {D.him} to the front office.\""),
               .direct("What did {DL} say to you?", "\"{D.He} told me, and I remember the words exactly, 'You'll regret this when I see you off school grounds.' {D.He} said it low, close to the fence, with other parents standing nearby.\""),
               .direct("Who else heard it?", "\"A coworker was standing three feet away at the gate. She heard the same sentence and wrote it down for the principal before the end of the day.\""),
               .direct("How did you feel when you heard it?", "\"I was afraid to walk to my car. I asked a colleague to walk out with me, and I did not park in my usual spot for a week.\""),
               .direct("What did the office record show?", "\"The school call log shows {DL} called the front office twice that afternoon, both times about the pickup. The calls came after I turned {D.him} away at the fence.\""),
               .direct("Did you report it?", "\"Yes, I told the principal that afternoon and filed a report the next morning. I wanted it on paper because {DL} had been in a case in this court before, and I knew that history.\""),
               .cross("Was the child safe the entire time?", "\"Yes, the child was inside with a teacher and was never in any danger. My concern was for myself, not for the child.\""),
               .cross("Was {DL} angry because you would not release the child?", "\"{D.He} was clearly angry, and I understand why a parent would be upset at a refusal. A refusal is still not a reason to say something like that.\""),
               .cross("Did {DL} touch you or raise a hand?", "\"No, {D.he} did not touch me or move toward me. The words and the tone were what frightened me.\""),
               .cross("You were following the approved list, weren't you?", "\"I was, and I would do it again. I am not allowed to release a child to anyone who is not on it.\""),
               .cross("Could 'off school grounds' have meant something harmless?", "\"It might have, to someone else. To me, coming from a person who was that angry, it sounded like a promise to find me.\"")],
        theory: ("{D} told a school employee 'you'll regret this when I see you off school grounds' and meant it as a threat.", "{D} was a frustrated parent who lost {D.his} temper at a pickup refusal and said something careless."),
        allocution: "\"I let my temper speak that afternoon at pickup, and I'm sorry. I was frustrated that the aide wouldn't release my child to me, and I said I'd see them later. I didn't mean it as a threat. I've been in this courtroom before, and I'll watch my words.\"",
        truths: ("{DL} had a prior case in this court and waited in a parked car after the school day ended.", "{V} had refused a pickup that was on the approved list, and {DL} had been told to stay away."),
        defendant: [.direct("Why did you go to the school that afternoon?", "\"I went to pick up my child, as I thought I was allowed to. When the aide would not release my child, I felt humiliated in front of other parents.\""),
               .direct("What did you say to {V} at the fence?", "\"I said something like I would see {V.him} later, off school grounds. I was frustrated and I did not choose my words well.\""),
               .direct("Did you mean to hurt anyone?", "\"No, I never meant to hurt anyone. It was a figure of speech from a person who had lost patience.\""),
               .direct("Why did you call the school office afterward?", "\"I called twice to get the situation straightened out and find out who could release my child. I wanted the issue resolved, not to threaten anyone.\""),
               .direct("What did you do after you left the fence?", "\"I sat in my car for a while, calming down, and then I went home. I did not follow {V} or wait to confront anyone.\""),
               .direct("How do you feel now about what you said?", "\"I am ashamed of it. I let my temper speak, and I know how it sounded to someone who was only doing the job.\""),
               .cross("You said 'you'll regret this,' didn't you?", "\"I said something close to that, and I wish I had not. I do not remember the exact words.\""),
               .cross("You mentioned seeing {V} 'off school grounds,' right?", "\"Yes, I said that, and I understand how it sounds. I meant that I would deal with it another way, not that I would hurt anyone.\""),
               .cross("You waited in a parked car after the school day ended, didn't you?", "\"I sat in my car for a short time. I was not waiting for {V}, I was trying to settle down before driving.\""),
               .cross("You called the office twice that afternoon, didn't you?", "\"Yes, because I was upset, and no one would tell me who could release my child.\""),
               .cross("You have been in this court before, in {PRIORDATE}, and you were told to watch your words?", "\"I was, and I should have remembered it at that fence.\"")],
        openings: ("At the afternoon pickup line, {V} would not release a child to {D}. A coworker three feet away heard {DL} say, 'You'll regret this when I see you off school grounds,' and the school's call log shows {DL} phoned the office twice.", "The defense will present a parent who was refused at a fence in front of other parents and who lost {D.his} temper for a moment. Bad words said in frustration, with nothing done afterward, are not a threat to injure."),
        closings: ("A coworker heard the words, {V} was afraid to walk to a car, and the call log shows {D} was still agitated an hour later. Words like that, from a person back in this court, are a threat.", "{D} said one careless sentence at a fence and then sat in a car and went home. Nothing {D.he} did afterward suggests a plan to hurt anyone, and the State has not proved a true threat."),
        timeline: [(0, "3:10 p.m.: {V} refuses to release the child at the pickup line."), (0, "3:12 p.m.: {DL} says 'You'll regret this when I see you off school grounds' within earshot of a coworker."), (0, "3:45 p.m.: {DL} calls the school office twice about the pickup."), (1, "{V} reports the threat to the principal and files a written report.")],
        identified: "The coworker who overheard.",
        mood: .indifferent)

    static let shoulderPassBack = SmallCases.make(
        key: "story.followup.shoulderPassBack",
        category: .traffic,
        headlines: ["Motorist Drives Along Shoulder to Skip Exit Backup", "Defendant From Highway Shooting Case Cited for Reckless Driving"],
        law: "recklessDriving",
        spec: "Drove a vehicle carelessly and heedlessly in willful or wanton disregard of the rights or safety of others, on {DATE}.",
        ages: 19...70,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a state trooper watched {D} pass a line of stopped cars on the shoulder for nearly a mile near an exit on {DATE}, passing within a few feet of a work crew. The trooper's dash camera recorded the speed. {DL} says traffic had stopped and {D.he} was in a hurry.",
        state: [E(.video, 3, "Dash Camera", "{D}'s vehicle passes on the shoulder at 42 mph."), E(.statement, 2, "Work Crew Member", "Jumped out of the way.")],
        defense: [E(.statement, 1, "Hurry", "{DL} says {D.he} had a delivery.")],
        role: "State trooper",
        exam: [.direct("What were you doing that afternoon?", "\"I was on patrol near an exit where traffic had backed up from a work crew in the right lane. I was parked on the median with my dash camera running.\""),
               .direct("What did you see?", "\"A vehicle came up the shoulder, passing a line of stopped cars for nearly a mile. It was {DL}'s vehicle, and it never slowed down.\""),
               .direct("How fast was it going?", "\"The dash camera shows 42 miles per hour on the shoulder. That is too fast for a shoulder with stopped cars and workers just beyond it.\""),
               .direct("What was beside the shoulder?", "\"A road crew was working, with cones and a truck parked right at the edge. {DL}'s vehicle passed within a few feet of them.\""),
               .direct("What did the crew do?", "\"One crew member jumped out of the way. He told me afterward that he did not see the vehicle until it was almost on him.\""),
               .direct("What did you do?", "\"I followed with my lights on and stopped {DL} at the next exit. I spoke with {D.him} at the window and wrote the citation.\""),
               .direct("Did {DL} say why?", "\"{D.He} said traffic was stopped and {D.he} was in a hurry. I asked where, and {D.he} said {D.he} had a delivery to make.\""),
               .cross("Did anyone get hit?", "\"No, nobody was struck. A crew member moved quickly and nobody was injured.\""),
               .cross("Was the shoulder clear of vehicles when {DL} passed?", "\"The shoulder had no stopped cars, but it had cones and the crew near the end. It is not meant to be used as a travel lane.\""),
               .cross("Was there a detour sign directing traffic to the shoulder?", "\"Not that I saw. There was a lane closure sign but nothing pointing anyone onto the shoulder.\""),
               .cross("The line of cars was stopped, wasn't it?", "\"Yes, it was, and that is why passing on the shoulder was dangerous. Those drivers were not expecting a car beside them.\""),
               .cross("Could {DL} see the crew from that distance?", "\"The crew was visible from a long way back. I could see them from my position, and the camera did too.\"")],
        theory: ("{D} used the shoulder as a passing lane and drove close to a road crew at 42 miles per hour.", "{D} was a rushed driver who saw the line was stopped and got through without meaning to put anyone in danger."),
        allocution: "\"I saw an opening on the shoulder and took it, and I should have waited. The line was stopped and I was in a hurry. I didn't see the work crew until I was past them. I've been in this courtroom before for driving like this. I'm sorry for the danger.\"",
        truths: ("{DL} had a prior case in this court and had just been cut off by a car near the exit.", "{DL} was following a detour sign that pointed onto the shoulder."),
        defendant: [.direct("Why did you use the shoulder?", "\"The line was stopped and I had a delivery that was already late. I saw an opening on the shoulder and took it.\""),
               .direct("What was your delivery?", "\"A package for a customer with a deadline. I was worried I would lose the job if I was late again.\""),
               .direct("Did you see the work crew?", "\"Not until I was past them. The cones were on my right and I was looking at the road ahead.\""),
               .direct("How fast do you think you were going?", "\"About forty, I believe. I was not looking at the speedometer, but I know it was faster than I should have been.\""),
               .direct("What did you do when the trooper stopped you?", "\"I pulled over, handed over my license, and told the trooper the truth about why I did it. I was not argumentative.\""),
               .direct("What do you regret about that afternoon?", "\"I regret that someone could have been hurt. I should have waited like everyone else.\""),
               .cross("You drove nearly a mile on the shoulder, didn't you?", "\"I did, and it was too far. I was impatient, and I did not stop to think.\""),
               .cross("You passed within a few feet of a crew, correct?", "\"I did, but I did not see them until I was already past. That is not an excuse.\""),
               .cross("You were in this court in {PRIORDATE} for driving, weren't you?", "\"Yes, I was, and I should have known better. I did not think about it in the moment.\""),
               .cross("Nobody told you to use the shoulder, did they?", "\"No one did. I looked at the line of stopped cars, saw the open shoulder, and made that choice myself, with nobody directing me anywhere.\""),
               .cross("You were not following a detour, were you?", "\"I thought there might have been a detour, but I was not sure. I did not see a sign.\"")],
        openings: ("A state trooper's camera shows {D} driving up the shoulder at 42 miles per hour, passing a line of stopped cars for nearly a mile and coming within a few feet of a road crew. A crew member jumped out of the way.", "The defense will present a driver with a late delivery who saw an opening and took it, did not see the crew until past them, and hit no one. Poor judgment is not the same as willful disregard."),
        closings: ("The video shows 42 miles per hour on a shoulder, a crew a few feet away, and a worker who had to jump. {D} had been in this court before for driving like this.", "{D} was in a hurry and saw a shoulder. Nobody was hit and the crew was seen only when {D.he} was past, and the State has not proved a willful disregard for safety."),
        timeline: [(0, "Afternoon: traffic backs up at the exit where a road crew is working."), (0, "{DL}'s vehicle passes the stopped cars on the shoulder at 42 miles per hour."), (0, "A crew member jumps out of the way as the vehicle passes."), (0, "The trooper stops {DL} at the next exit and issues a citation.")],
        identified: "The trooper's camera.",
        mood: .indifferent)

    static let closedStoreLotBack = SmallCases.make(
        key: "story.followup.closedStoreLotBack",
        category: .property,
        headlines: ["Shopper Returns to Closed Store Lot After Written Trespass Warning", "Defendant From Robbery Case Charged With Second-Degree Trespass"],
        law: "trespass2",
        spec: "Entered and remained on premises of {V} after being notified not to enter, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, the owner of a hardware store, {V}, gave {D} a written trespass notice. On {DATE}, a camera showed {DL} walking the fenced lot after closing. {DL} says {D.he} was cutting through to a bus stop.",
        state: [E(.document, 3, "Trespass Notice", "Signed by {D} three weeks earlier."), E(.video, 2, "Lot Camera", "{D} walks the lot at 9:40 p.m.")],
        defense: [E(.statement, 1, "Bus Stop", "{DL} says it is the way to the bus.")],
        role: "Store owner",
        exam: [.direct("What kind of business do you run?", "\"I own a hardware store. We sell lumber, tools, and building supplies, and the lot behind the store is fenced because we keep stock out there.\""),
               .direct("Did {D} receive a notice not to enter?", "\"Yes, I gave {DL} a written trespass notice about three weeks before this. {D.He} signed it, and I kept the copy.\""),
               .direct("Why did you give the notice?", "\"There had been trouble at the store, and {DL} was in this court after that. I wanted {D.him} off the property.\""),
               .direct("What did the lot camera show?", "\"It shows {DL} walking along the fenced lot at 9:40 at night, after we had closed. It shows {D.him} walking the length of the property.\""),
               .direct("Was the lot supposed to be open that night?", "\"No. We lock the lot at closing, and the fence is clearly marked with signs. Nobody has permission to be there after hours.\""),
               .direct("How did you learn about it?", "\"I reviewed the camera the next morning. I recognized {DL} right away from the earlier trouble.\""),
               .direct("What did you do?", "\"I called the sheriff's office and gave them the notice and the footage. I did not confront anyone.\""),
               .cross("Is there a public path next to the lot?", "\"Yes, there is a sidewalk along the street. It runs in front of the store and down to the bus stop.\""),
               .cross("So {DL} could have gotten to the bus stop on the sidewalk, couldn't {D.he}?", "\"It is possible. The sidewalk is a little longer, and it does flood in heavy rain.\""),
               .cross("Did {DL} take anything from the lot?", "\"Not that I found. Nothing was missing from the stock that night.\""),
               .cross("Did {DL} damage the fence or gate?", "\"Nothing was damaged that I could see. The gate was shut, but there is a gap by the loading dock.\""),
               .cross("Was the notice clear about the lot?", "\"It said not to enter any part of the property. The lot is part of it.\"")],
        theory: ("{D} came back onto the store's lot after being given a written notice not to enter.", "{D} was cutting through a lot to a bus stop and meant no harm to anyone."),
        allocution: "\"I took the shortcut through that fenced lot to reach my bus, and I should have walked around. I knew about the notice, and I'm sorry. I've been in this courtroom before, and I know I'm not welcome there. I'll use the sidewalk from now on.\"",
        truths: ("{DL} had a prior case in this court and tried a locked gate on the way through.", "The bus stop is directly across the lot and the street path floods."),
        defendant: [.direct("Did you receive a written notice from {V}?", "\"Yes, I did, and I signed it about three weeks before. I understood that I was not supposed to come onto the store's property.\""),
               .direct("Why did you walk through the lot?", "\"It is the shortest way to the bus stop, and I was running late. The sidewalk is much longer.\""),
               .direct("How did you get into the lot?", "\"The gate was in my way, so I went through the gap by the loading dock. I did not climb or break anything.\""),
               .direct("Did you take anything?", "\"No, I did not take or touch anything. I just walked across the lot to the other side.\""),
               .direct("What time was it, and why were you out?", "\"About 9:40 at night, coming back from a late shift. I was tired, and I wanted to catch the last bus.\""),
               .direct("How do you feel about it?", "\"I know I should have used the sidewalk. I am sorry to {V}, and I will stay off that property.\""),
               .cross("You knew about the notice, didn't you?", "\"Yes, I did, and I had it in mind. I took the chance anyway.\""),
               .cross("You tried the gate before going around it, didn't you?", "\"I did try it, and it was locked. Then I went through the gap.\""),
               .cross("The lot was closed and fenced, wasn't it?", "\"It was fenced, and it was dark. I should have known better.\""),
               .cross("You were in this court before, in {PRIORDATE}, for something related to the store, weren't you?", "\"Yes, I was, and that is why I was given the notice. I understand why {V} was upset to see me.\""),
               .cross("The sidewalk was not blocked that night, was it?", "\"No, but it was flooded in places. That is why I cut through.\"")],
        openings: ("Three weeks after {V} gave {D} a written trespass notice, a camera caught {DL} walking the fenced lot at 9:40 p.m., long after closing. {DL} signed the notice, and {DL} had been in this court before about the store.", "The defense will present a worker coming home from a late shift who took the shortest way to a bus stop, touched nothing, and left. Cutting through a lot to a bus is not what the notice was meant to stop."),
        closings: ("{D} signed the notice, and three weeks later the camera shows {D.him} inside the fenced lot after closing. {D.He} knew what the notice said.", "The sidewalk floods, the last bus was coming, and {D} took a shortcut across an empty lot without touching a thing. The State has not shown the kind of entry the notice was meant to prevent."),
        timeline: [(-21, "{V} gives {D} a written trespass notice, and {D} signs it."), (0, "9:40 p.m.: {D} walks across the closed, fenced lot."), (1, "{V} reviews the lot camera and recognizes {DL}."), (1, "{V} reports it to the sheriff's office with the notice and the footage.")],
        identified: "The lot camera.",
        mood: .indifferent)

    static let flowersNoteBack = SmallCases.make(
        key: "story.followup.flowersNoteBack",
        category: .violent,
        headlines: ["Bouquet With Handwritten Note Delivered to Protected Person", "Defendant From Kidnapping Case Charged With Violating Protective Order"],
        law: "dvpoViolation",
        spec: "Willfully violated a valid protective order by contacting {V} through a delivery, on {DATE}.",
        ages: 22...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} received a flower delivery at work on {DATE} with a handwritten note. A florist records showed {D} had paid in cash and given {D.his} name. A protective order barred contact. {DL} says the flowers were an apology and not a message.",
        state: [E(.document, 3, "Florist Receipt", "Paid in cash under {D}'s name."), E(.physical, 2, "Note", "Handwriting matches {D}'s.")],
        defense: [E(.statement, 1, "Apology", "{DL} says it was only an apology.")],
        role: "Florist",
        exam: [.direct("What do you do for a living?", "\"I am a florist. I run a small shop downtown, and I take orders in person, by phone, and online.\""),
               .direct("Did {DL} place an order with you?", "\"Yes, {DL} came in and ordered a bouquet for delivery to a workplace. I wrote it up on a standard order form.\""),
               .direct("How did {DL} pay?", "\"In cash. {D.He} counted it out at the counter and gave me {D.his} name for the receipt.\""),
               .direct("What did {DL} write on the card?", "\"A handwritten note that was an apology, with a phone number at the bottom. I saw {D.him} write it.\""),
               .direct("Was the card signed?", "\"With a first name only, but the receipt has {DL}'s full name on it. The writing matches the note.\""),
               .direct("Whom did the delivery go to?", "\"It went to {V}'s workplace. I took the address from {DL} and sent one of my drivers.\""),
               .direct("Did you know anything about an order of protection?", "\"No. If I had known, I would not have accepted the order. Nobody told me.\""),
               .cross("So {DL} signed the receipt with {D.his} real name?", "\"Yes, {D.he} did, and {D.he} did not try to hide who {D.he} was.\""),
               .cross("Did {DL} seem to be trying to disguise the order?", "\"No, {D.he} was polite and calm. I did not have any reason to think it was a problem.\""),
               .cross("Was it a bouquet with an apology only?", "\"Yes, the note was an apology and a phone number. I did not see any threat in it.\""),
               .cross("You do not know what the order of protection says, do you?", "\"No, I never saw it. I only know what the detective told me afterward.\""),
               .cross("{DL} did not try to deliver it personally, did {D.he}?", "\"No, {D.he} left it to us. I cannot say what {D.he} would have done otherwise.\"")],
        theory: ("{D} contacted a protected person by sending flowers and a note to {V}'s workplace.", "{D} sent a single apology and did not understand that the order covered it."),
        allocution: "\"I should have left it alone, and I'm sorry. I sent those flowers as an apology, with a handwritten note, and I know there's an order against contact. I've been in this courtroom before, and I know better. I won't send anything again.\"",
        truths: ("{DL} had a prior case in this court and asked the florist to deliver the bouquet to {V}'s workplace.", "The order was served only two days earlier and {DL} had a letter saying it was unclear."),
        defendant: [.direct("Did you send flowers to {V}?", "\"Yes, I did. I ordered a bouquet and wrote a note with it.\""),
               .direct("Why did you send them?", "\"To apologize. I felt bad about how things ended, and I wanted to say sorry.\""),
               .direct("Did you know about the protective order?", "\"Barely. It had been served only two days before, and I did not fully understand what it covered.\""),
               .direct("What did the order say, as you understood it?", "\"I thought it was about coming to the house. I did not realize a delivery to a workplace counted.\""),
               .direct("Why did you put your name and number on the card?", "\"I wanted {V} to know it was sincere. I was not trying to hide.\""),
               .direct("How do you feel about it now?", "\"I should have left it alone. I am sorry for the trouble I caused.\""),
               .cross("You knew there was an order, didn't you?", "\"I knew there was something, but I had a letter that said it was unclear. I did not read it carefully.\""),
               .cross("You paid in cash and gave your name, didn't you?", "\"Yes, I did, because I had nothing to hide. I walked into the shop, wrote my own name on the receipt, and did not try to disguise anything about the order.\""),
               .cross("You were in this court before, in {PRIORDATE}, and knew how orders work?", "\"Yes, I was, and I should have paid closer attention to what I was doing.\""),
               .cross("The note included your phone number, didn't it?", "\"Yes, it did. I thought {V} might want to call.\""),
               .cross("You asked the florist to deliver it to {V}'s workplace, didn't you?", "\"I did, because I did not have a home address that I could use.\"")],
        openings: ("{V} was served with a bouquet and a handwritten note at work while a protective order barred contact. A florist's receipt shows {D} paid in cash under {D.his} own name, and the handwriting on the note matches.", "The defense will present a person who had been served only two days earlier, did not understand the order, and sent a single apology under {D.his} own name. That is a mistake about a document, not a defiance of one."),
        closings: ("The order barred contact. The receipt carries {D}'s name, the note carries {D}'s handwriting and phone number, and the bouquet went to {V}'s workplace.", "One apology, signed and paid for in the open, two days after the order was served. {D} did not understand it, and the State has not proved a willful violation."),
        timeline: [(-2, "The protective order is served on {D}."), (0, "{D} orders a bouquet in cash at the florist's shop and writes a note with a phone number."), (0, "The bouquet is delivered to {V}'s workplace."), (1, "{V} reports the delivery to law enforcement.")],
        identified: "The florist's receipt.",
        mood: .wantsConviction)

    static let mysteryBoxBack = SmallCases.make(
        key: "story.followup.mysteryBoxBack",
        category: .whiteCollar,
        headlines: ["'Mystery Box' Seller Ships Bricks to Online Buyers", "Defendant From Mailbox Case Charged With Obtaining Property by False Pretenses"],
        law: "falsePretenses",
        spec: "By false pretense, obtained $780 from {V} with intent to cheat and defraud, on or about {DATE}.",
        ages: 25...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} paid $780 online for 'returns mystery boxes' advertised by {D}. The parcels contained bricks and packing paper. Four other buyers reported the same. {DL} says {D.he} sold boxes as-is and never promised contents.",
        state: [E(.digital, 3, "Listing", "Posts promise electronics in every box."), E(.physical, 2, "Parcels", "Four boxes of bricks and paper.")],
        defense: [E(.statement, 1, "As Is", "{DL} says boxes were sold as-is.")],
        role: "Buyer",
        exam: [.direct("What did you see in the listing?", "\"The listing said every returns mystery box held name-brand electronics. It used photos of laptops, tablets, and headphones.\""),
               .direct("How much did you pay?", "\"I paid $780 online for several boxes. I thought that was a fair price for what was pictured.\""),
               .direct("What arrived?", "\"Four boxes arrived. Inside there were bricks and packing paper, nothing else, and not a single electronic item.\""),
               .direct("What did you do when you opened them?", "\"I took photos and emailed the seller right away. I got no response for two days.\""),
               .direct("What happened after that?", "\"I found other buyers online who said the same thing happened to them. Four other people reported the same to the sheriff's office.\""),
               .direct("What did the seller say, if anything?", "\"A message came three days later saying all sales were final and the boxes were sold as is. That was the first I heard of it.\""),
               .direct("How does that compare to the listing?", "\"The listing promised electronics in every box. I did not see anything about as-is until the message.\""),
               .cross("Does the listing say sold as-is anywhere?", "\"In small print at the bottom of the page, yes. I did not see it until later.\""),
               .cross("Did you see the boxes before you bought them?", "\"No, they were sealed, and the photos were stock images.\""),
               .cross("The listing used the words mystery boxes, didn't it?", "\"Yes, it did, but I understood that to mean surprise electronics, not bricks.\""),
               .cross("Did you ask the seller for a refund?", "\"I did, and I was told no. Two other buyers got refunds, I learned later.\""),
               .cross("You knew you were buying sealed boxes?", "\"I knew they were sealed. I did not think they would hold nothing of value.\"")],
        theory: ("{D} sold mystery boxes advertised as electronics that held only bricks and paper.", "{D} sold sealed boxes as is and promised no particular contents."),
        allocution: "\"The listings should have been clearer, and I'll refund what I can. I sold those boxes sealed and as-is, and I used stock images, and I never promised any contents. I know the buyers got bricks and packing paper. I've been in this courtroom before, and I'm sorry.\"",
        truths: ("{DL} had a prior case in this court and posted photos of electronics that were not in the boxes.", "{DL} refunded two buyers who complained and kept a ledger of the sales."),
        defendant: [.direct("Did you put bricks in those boxes?", "\"No, I did not. The boxes were sealed when I got them, and I shipped them as they came.\""),
               .direct("Where did the boxes come from?", "\"I bought sealed returns boxes from a liquidator and resold them. I never knew what was inside.\""),
               .direct("What did the listing photos show?", "\"Stock images of electronics. I used them because I did not have photos of what was inside.\""),
               .direct("Did you promise any contents?", "\"Never. I wrote 'sold as is' in the listing, and I said that if they did not like it they could take the risk.\""),
               .direct("Did you refund anyone?", "\"Two buyers who complained got their money back. I kept a ledger of all the sales.\""),
               .direct("What do you say to the buyers?", "\"I am sorry they got bricks, and I will refund what I can. I should have made the terms clearer.\""),
               .cross("The listing promised electronics in every box, didn't it?", "\"It said name-brand electronics, but I meant it as general. I should have been careful.\""),
               .cross("You knew the photos were not of the actual contents, didn't you?", "\"Yes, they were stock images. I thought that was common.\""),
               .cross("Four buyers got bricks, correct?", "\"That is what I have heard. I did not know until they complained.\""),
               .cross("You were here in {PRIORDATE} for {PRIOR}, weren't you?", "\"Yes, I was, and I know that does not help me.\""),
               .cross("You refunded only two, didn't you?", "\"Yes, two, and I told the others I would work something out.\"")],
        openings: ("{D} listed returns mystery boxes with photos of name-brand electronics, and {V} paid $780. The boxes held bricks and packing paper, and four other buyers say the same thing happened to them. {DL} has been in this court before.", "The defense will present a seller who offered sealed boxes as is, used stock photos like many sellers do, and refunded the buyers who complained. A bad box is a bad bargain, but it is not a lie."),
        closings: ("The listing promised electronics in every box, and every box held a brick. Four other buyers got the same thing, and {D} refunded only two.", "Sealed boxes, sold as is, with a ledger and refunds for those who asked. A buyer's disappointment is not proof that {D} meant to cheat anyone."),
        timeline: [(-14, "{D} posts a listing for returns mystery boxes with photos of electronics."), (0, "{V} pays $780, and the boxes arrive with bricks and packing paper inside."), (3, "{D} replies that the boxes were sold as is."), (7, "Four other buyers report the same, and the sheriff's office takes the complaints.")],
        identified: "The online listing.",
        mood: .wantsConviction)

    static let stolenTruckReportBack = SmallCases.make(
        key: "story.followup.stolenTruckReportBack",
        category: .publicOrder,
        headlines: ["Truck Reported Stolen Turns Up in Relative's Barn", "Defendant From Robbery Case Charged With Making a False Police Report"],
        law: "falseReport",
        spec: "Willfully made a false report to a law enforcement officer that a crime had been committed, on {DATE}.",
        ages: 22...55,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} told a deputy on {DATE} that {D.his} pickup had been stolen from a grocery store lot overnight. Two days later a deputy found the truck in a relative's barn with the plates removed. {DL} says {D.he} believed the truck had been taken and that a relative moved it without telling {D.him}.",
        state: [E(.physical, 3, "Truck", "Found in a relative's barn with the plates removed."), E(.document, 2, "Report", "{D}'s signed report that the truck was stolen.")],
        defense: [E(.statement, 1, "Relative", "{DL} says a relative moved the truck without asking.")],
        role: "Sheriff's deputy",
        exam: [.direct("What report did {D} make to you?", "\"{D} told me {D.his} pickup had been stolen overnight from a grocery store lot. {D.He} signed a written report that I took down.\""),
               .direct("What did you do after the report?", "\"I took the information, entered the truck as stolen, and began a search. I told {DL} someone would call with updates.\""),
               .direct("Where was the truck eventually found?", "\"Two days later I found it in a relative's barn on a back road. The plates had been taken off.\""),
               .direct("What did you see on the truck?", "\"The truck was in good condition, parked in a stall, with the plates removed and set against a wall. There was no sign of forced entry.\""),
               .direct("Who moved the truck?", "\"The relative told me {DL} had asked for the use of the barn the night before the report. I wrote that down.\""),
               .direct("What did you learn about the truck's payments?", "\"The lender told me {DL} owed three payments. That was a reason for me to wonder about the report.\""),
               .direct("What did you do next?", "\"I spoke with {DL} about it. {D.He} said {D.he} thought it had been taken and that a relative had moved it without telling {D.him}.\""),
               .cross("The relative said {DL} asked for the barn the night before?", "\"That is what I was told, yes. The relative also said {DL} did not mention a report.\""),
               .cross("Did {DL} know where the truck was when {D.he} made the report?", "\"I cannot say that. I only know what I was told.\""),
               .cross("Is it possible the relative moved it without telling {DL}?", "\"It is possible. The relative's account and {DL}'s account do not match, and I cannot resolve that.\""),
               .cross("Did you find the plates in the barn?", "\"Yes, they were in the barn, on a shelf. Nobody can say who took them off.\""),
               .cross("Was the truck damaged or missing anything?", "\"No, nothing was missing. It looked as if it had been put away on purpose.\"")],
        theory: ("{D} reported a truck stolen when it was hidden in a relative's barn with the plates off.", "{D} honestly believed the truck was stolen and was misled by a relative who moved it."),
        allocution: "\"I should have checked first, and I'm sorry. I thought my truck had been stolen when I couldn't find it in the lot, and a relative had moved it behind a barn without telling me. I've been in this courtroom before, and I know how that looked to the deputy.\"",
        truths: ("{DL} had a prior case in this court and owed three payments on the truck.", "The relative says {DL} asked for the barn the night before the report."),
        defendant: [.direct("Why did you report the truck stolen?", "\"I parked it in a grocery store lot, and when I came back it was gone. I thought someone had taken it.\""),
               .direct("When did you last see it?", "\"The evening before. I left it in the lot overnight because I was getting a ride home.\""),
               .direct("Did you know it was in a barn?", "\"No, I did not. I only learned that when the deputy told me.\""),
               .direct("Did you take off the plates?", "\"No, I did not. I have no idea who did.\""),
               .direct("Who is the relative?", "\"A cousin who has a barn. He moved the truck without telling me, and I do not know why.\""),
               .direct("What did you do when you heard?", "\"I called the relative and asked. We talked, and I signed the form the deputy gave me.\""),
               .cross("You were behind on payments, weren't you?", "\"I was, by three payments. That did not have anything to do with the report.\""),
               .cross("The relative says you asked for the barn, doesn't he?", "\"He says that. I never asked him, and I do not know why he would say so.\""),
               .cross("You made a signed report that the truck was stolen, correct?", "\"Yes, I signed it, because at that moment I truly believed the truck had been taken. I had walked the whole lot and could not find it anywhere.\""),
               .cross("You were in this court before, in {PRIORDATE}, weren't you?", "\"Yes, I was. That is why I hoped this would be straightforward.\""),
               .cross("You did not check with family before calling the deputies?", "\"No, I did not. I should have, and I have said so.\"")],
        openings: ("{D} reported {D.his} pickup stolen from a grocery lot, and two days later a deputy found it in a relative's barn with the plates removed. {D} was behind on three payments on that truck, and the relative says {D.he} asked for the barn.", "The defense will present a person who left a truck in a lot and returned to find it gone, and a relative who moved it without a word. An honest mistake about a missing truck is not a false report."),
        closings: ("The signed report says stolen, the barn says hidden, the plates say someone wanted it off the books, and the lender says three payments were behind.", "{D} reported what {D.he} believed. The relative moved the truck, the relative's account is the only link to {D}, and the State has not shown that {D} knew the report was false."),
        timeline: [(-1, "{D} leaves the truck in the grocery store lot for the night."), (0, "{D} reports the truck stolen and signs a written report."), (2, "A deputy finds the truck in a relative's barn with the plates removed."), (3, "The relative tells the deputy that {DL} had asked for the barn the night before.")],
        identified: "The deputy's search.",
        mood: .indifferent)

    static let soccerSidelineBack = SmallCases.make(
        key: "story.followup.soccerSidelineBack",
        category: .publicOrder,
        headlines: ["Parent Ejected From Youth Soccer Game After Shouting Match", "Defendant From Protective Order Case Charged With Disorderly Conduct"],
        law: "disorderly",
        spec: "Engaged in disorderly conduct at a public gathering, disturbing a public event, on {DATE}.",
        ages: 25...55,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a referee ejected {D} from a youth soccer game on {DATE} for shouting at a coach and refusing to leave the sideline. Other parents recorded it. {DL} says {D.he} only spoke up for the children.",
        state: [E(.video, 3, "Parent Video", "{D} shouts and refuses to leave."), E(.statement, 2, "Referee", "Asked {D} three times to leave.")],
        defense: [E(.statement, 1, "For the Children", "{DL} says it was about a rule.")],
        role: "Referee",
        exam: [.direct("What is your role at the field?", "\"I am a certified youth referee. I work weekend games for the league, and I have refereed this age group for six years.\""),
               .direct("What happened during the game?", "\"A parent, {DL}, started shouting at a coach from the sideline. It kept going and got louder, and children on both teams could hear it.\""),
               .direct("What did you do?", "\"I stopped play and walked to the sideline. I asked {DL} to stop and to leave the area.\""),
               .direct("How many times did you ask?", "\"Three times. The first two times {DL} kept talking, and the third time {D.he} said {D.he} was not leaving.\""),
               .direct("Who was present?", "\"Dozens of children and a few dozen parents. Several of the parents recorded it on their phones.\""),
               .direct("What did you do when {DL} would not leave?", "\"I called a halt to the game and told both coaches we would wait. After several minutes {DL} stepped back and the game went on.\""),
               .direct("Had you seen {DL} before?", "\"The league had told {DL} earlier to stay off the sideline. I was told that before the game.\""),
               .cross("What was {DL} shouting about?", "\"A rule about substitutions, I think. {D.He} also used some words I will not repeat.\""),
               .cross("Did the coach say something first?", "\"The league has a complaint about the coach, but I did not hear it myself.\""),
               .cross("Did {DL} touch anyone?", "\"No, nobody was touched, and nobody was threatened physically. It was all shouting, but it was loud enough that the children on both teams stopped playing to look.\""),
               .cross("Did {DL} say {D.he} heard you?", "\"{D.He} said {D.he} did not hear me the first time. I do not think that was true.\""),
               .cross("How long did the delay last?", "\"About five minutes from the time I stopped play until {DL} stepped back, and then the game resumed. The kids were standing around the whole time waiting.\"")],
        theory: ("{D} disrupted a youth soccer game by shouting and refusing to leave.", "{D} was a parent who spoke up about a rule and left when it was clear {D.he} had to."),
        allocution: "\"I let the game get to me, and I'm sorry. I was speaking up for the kids, and I refused to leave when the referee asked, and I should have walked away. I've been in this courtroom before, and I know I'm setting a bad example. I'll stay home from games.\"",
        truths: ("{DL} had a prior case in this court and was told earlier by the league to stay off the sideline.", "The coach had used a profanity first and the league confirmed a complaint."),
        defendant: [.direct("Why did you shout at the coach?", "\"I was speaking up about a rule that I thought was being applied wrong. A child was being kept out unfairly.\""),
               .direct("What did you say?", "\"I said it loudly, and I used a word I should not have. I was upset.\""),
               .direct("When did you hear the referee?", "\"The second time, I think. I wanted to finish what I was saying, and then I left.\""),
               .direct("Did you refuse to leave?", "\"At first, yes. After the third request I walked off, and the game restarted.\""),
               .direct("Why were you at the sideline?", "\"My child plays, and I go to every game. I did not know I was not supposed to be there.\""),
               .direct("What do you wish you had done?", "\"I wish I had stayed in my chair. I am setting a poor example for the children.\""),
               .cross("You shouted at a coach in front of children, didn't you?", "\"Yes, I did, and I am not proud of it.\""),
               .cross("You were asked to leave three times, weren't you?", "\"I was, and I did not move right away. I did not hear the first one.\""),
               .cross("You were in this court before, in {PRIORDATE}, weren't you?", "\"Yes, I was, and I should have remembered that day when I stood at that sideline. I let my temper get ahead of me again.\""),
               .cross("Your league told you to stay off the sideline earlier, didn't they?", "\"They did tell me that, and in the heat of the moment I forgot it. I should have taken a seat in the stands as they asked.\""),
               .cross("The coach had not touched anyone, had he?", "\"No, he had not, and I should not have shouted.\"")],
        openings: ("In the middle of a youth soccer game, {D} began shouting at a coach, and a referee asked {DL} three times to leave the sideline. Parents recorded it, and dozens of children heard.", "The defense will present a parent who spoke up about a rule and who walked away within minutes. A loud moment on a sideline, with a coach who also drew a complaint, is not a crime."),
        closings: ("The video shows the shouting, the referee asked three times, and the game stopped. {D} had been told to stay off that sideline and did not.", "A parent who cared about a child's playing time spoke too loudly. {D} left when it became clear, and the State has not proved a disturbance meant to disrupt."),
        timeline: [(0, "Kickoff of the youth soccer game."), (0, "{D} shouts at a coach from the sideline and the referee halts play."), (0, "The referee asks {D} to leave three times before {D.he} steps back."), (1, "The referee files a report and the league reviews the parent videos.")],
        identified: "The referee's report.",
        mood: .indifferent)

    static let cabinClaimBack = SmallCases.make(
        key: "story.followup.cabinClaimBack",
        category: .whiteCollar,
        headlines: ["Hunting Cabin 'Break-In' Claim Questioned by Insurer", "Defendant From Sheriff Funds Case Charged With Insurance Fraud"],
        law: "insuranceFraud",
        spec: "With intent to defraud, presented a claim to an insurer for $18,400 for items not stolen, on {DATE}.",
        ages: 45...75,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} filed a claim for $18,400 after reporting a break-in at a hunting cabin on {DATE}. An investigator found the 'stolen' rifles and a television listed for sale online by {DL}'s relative. {DL} says the items were sold earlier and the claim was a mistake by a clerk.",
        state: [E(.digital, 3, "Online Listing", "The claimed items listed for sale before the report."), E(.document, 2, "Claim Form", "Lists rifles and a television.")],
        defense: [E(.statement, 1, "Clerk's Mistake", "{DL} says a clerk filled in the form.")],
        role: "Insurance investigator",
        exam: [.direct("What is your job?", "\"I am an insurance investigator. I examine claims that look unusual and decide whether they match the facts.\""),
               .direct("What claim did you look into?", "\"{D} filed a claim for $18,400 after reporting a break-in at a hunting cabin. The claim listed rifles and a television as stolen.\""),
               .direct("What did you find?", "\"I searched online and found the same rifles and the television listed for sale. The listings predated the break-in report.\""),
               .direct("Who posted them?", "\"A relative of {DL}'s. The account was in the relative's name, and the dates are in the listings.\""),
               .direct("What does the claim form show?", "\"It lists the rifles and a television with serial numbers. {D.He} signed it as accurate.\""),
               .direct("What did you do next?", "\"I compared the listing dates to the date of the report. The items were for sale before the cabin was supposedly broken into.\""),
               .direct("What was the total of the claim?", "\"It came to $18,400, which is the value assigned to the rifles and the television listed on the claim form. That was the amount {D} asked the company to pay.\""),
               .cross("{DL} says a clerk filled in the form, doesn't {D.he}?", "\"That is what {D.he} says. The form is in {D.his} name, and {D.he} signed it.\""),
               .cross("Did the clerk confirm that?", "\"The clerk told me {D.he} filled out the form from a list {D.he} was given. {D.He} said {D.he} did not check each item.\""),
               .cross("Some of the items could have been sold before the break-in, couldn't they?", "\"Yes, and some were. That is a problem, because the claim says they were taken.\""),
               .cross("Was there a break-in at the cabin?", "\"There was evidence of one, yes. A door was forced, and some items were missing.\""),
               .cross("Who owned the rifles?", "\"{DL} did. The registration and the purchase papers are in {D.his} name, so there is no dispute about who owned them or who was entitled to make a claim.\"")],
        theory: ("{D} claimed items that had already been listed for sale.", "{D} signed a claim form that a clerk filled in and did not check it carefully."),
        allocution: "\"I should have read the form more carefully. Some of those items were sold earlier, and a clerk made a mistake on the claim. I'll correct it and repay the insurer whatever is owed.\"",
        truths: ("{DL} had a prior case in this court and signed the claim form as correct.", "The clerk confirmed filling in the form from a list {DL} provided."),
        defendant: [.direct("Did you file this claim?", "\"Yes, I did. I filed it after the cabin was broken into.\""),
               .direct("Did you sign the form?", "\"I did sign it. I read part of it, and I trusted that it matched my list.\""),
               .direct("Were some of the items sold earlier?", "\"Some were, yes. I had sold a few things before the break-in, and I did not update my list.\""),
               .direct("Who filled out the form?", "\"A clerk at the agent's office. I gave a list, and the clerk put it into the form.\""),
               .direct("Did you intend to cheat the insurer?", "\"No. I intended to claim what was taken, and I did not think carefully about what had been sold.\""),
               .direct("What will you do now?", "\"I will correct the claim and repay whatever I was paid.\""),
               .cross("You signed the form, didn't you?", "\"Yes, I did sign it, at the agent's office, after the clerk had put my list into the form. I should have read each line before I put my name on it.\""),
               .cross("The rifles were listed for sale before the break-in, weren't they?", "\"A relative listed them, yes. I did not think about the dates.\""),
               .cross("You gave the clerk the list, didn't you?", "\"Yes, I gave the clerk a list of what I remembered being in the cabin. I should have checked it against what I had sold before I handed it over.\""),
               .cross("You were in this court before, in {PRIORDATE}, weren't you?", "\"Yes, I was, and I should have been more careful.\""),
               .cross("$18,400 is a lot of money, isn't it?", "\"It is, and that is why I should have checked the form.\"")],
        openings: ("{D} reported a break-in at a hunting cabin and filed a claim for $18,400, listing rifles and a television as stolen. An investigator found the same items listed for sale online before the report, posted by {D.his} relative.", "The defense will present a person who sold some items earlier, gave a clerk a list, and signed a form without reading every line. A careless form is not a fraud."),
        closings: ("The items were for sale before the report, the form was signed, and the total was $18,400. {D} was in this court before and knew the stakes.", "A clerk filled in the form from a list. {D} signed it and has offered to repay. The State has not shown that {D} meant to defraud anyone."),
        timeline: [(-30, "Rifles and a television from the cabin are listed for sale online by a relative of {D}."), (0, "{D} reports a break-in at the hunting cabin and files a claim for $18,400."), (10, "The insurer's investigator finds the earlier online listing."), (12, "{D} says a clerk filled in the claim form.")],
        identified: "An online listing.",
        mood: .indifferent)

    static let jobsiteToolboxBack = SmallCases.make(
        key: "story.followup.jobsiteToolboxBack",
        category: .property,
        headlines: ["Contractor's Truck Toolboxes Pried Open at Job Site", "Defendant From Storage Unit Case Charged With Breaking Into a Vehicle"],
        law: "breakingVehicle",
        spec: "Broke and entered a motor vehicle of {V} with intent to commit larceny therein, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} found the truck toolboxes pried open at a job site on {DATE} and $1,900 in tools missing. A neighbor's camera showed {D} near the truck. {DL} says {D.he} was only looking at the house under construction.",
        state: [E(.video, 3, "Neighbor Camera", "{D} beside the truck at dusk."), E(.physical, 2, "Pry Marks", "Fit a flat bar in {D}'s car.")],
        defense: [E(.statement, 1, "Looking", "{DL} says {D.he} was looking at the house.")],
        role: "Contractor",
        exam: [.direct("What is your trade?", "\"I am a contractor, and I do framing and trim work. My tools are how I make a living.\""),
               .direct("What did you find at the job site?", "\"The toolboxes on my truck were pried open and about $1,900 in tools were missing. I found them when I arrived the next morning.\""),
               .direct("How were the boxes opened?", "\"With a flat bar, from the look of the marks. The lids were bent at the latches.\""),
               .direct("What did the neighbor's camera show?", "\"It shows {DL} standing beside my truck at dusk. {D.He} is there for a few minutes and then walks off.\""),
               .direct("What did the pry marks match?", "\"A deputy found a flat bar in {DL}'s car that fits the marks. The width matches.\""),
               .direct("Did you give {DL} permission to be near the truck?", "\"No. I did not know {D.him} and never gave anyone permission to touch my truck.\""),
               .direct("What did it cost you?", "\"$1,900 in tools and two days of work. I had to borrow tools from another contractor.\""),
               .cross("Was {DL} seen taking anything?", "\"No, the camera does not show that. It shows {D.him} standing beside the truck.\""),
               .cross("The house under construction is next to your truck, isn't it?", "\"Yes, it is. People do stop to look at it.\""),
               .cross("Is a flat bar a common tool?", "\"Yes, it is. Every contractor I know has one in the truck, and I have three myself, so the bar alone does not tell me who opened those boxes.\""),
               .cross("Could the marks have been made by a different bar?", "\"I cannot say that for sure. The deputy says this one fits.\""),
               .cross("You were not there at dusk, were you?", "\"No, I left earlier. I only know what the camera shows.\"")],
        theory: ("{D} pried open a contractor's truck toolboxes and took $1,900 in tools.", "{D} was a passerby who stopped to look at a house and touched nothing."),
        allocution: "\"I was wrong to stop at that job site, and I'm sorry. I only wanted to look at the house under construction, and I stood near the truck. I never opened a toolbox.\"",
        truths: ("{DL} had a prior case in this court and sold similar tools at a flea market the same weekend.", "The flat bar was in the car for changing tires."),
        defendant: [.direct("Did you open those toolboxes?", "\"No, I never did. I did not touch the truck.\""),
               .direct("Why were you at the job site?", "\"I was looking at the house that was being built. I like seeing new construction.\""),
               .direct("Why were you beside the truck?", "\"It was close to the street, and I stood by it to look at the house. I did not touch anything.\""),
               .direct("Whose flat bar is in your car?", "\"It is mine. I keep it behind the seat for changing tires and prying hubcaps, and I have had it for years. I did not use it on anyone's truck.\""),
               .direct("What did you do after you left?", "\"I went home. I did not know anything had happened until the deputy came.\""),
               .direct("Why do you think you were suspected?", "\"Because the camera shows me by the truck, and because of the earlier case. I understand that.\""),
               .cross("You were beside the truck at dusk, weren't you?", "\"Yes, I was, for a few minutes while I looked at the framing on the house next to it. I never touched the truck or the toolboxes.\""),
               .cross("The flat bar fits the marks, doesn't it?", "\"I am told it does, and so would many others.\""),
               .cross("You were in this court before, in {PRIORDATE}, weren't you?", "\"Yes, I was, and I know that is why I was a suspect.\""),
               .cross("You had no reason to be near the truck, did you?", "\"I had a reason, which was the house. I did not need to be near the truck.\""),
               .cross("Nobody else was seen at the truck, were they?", "\"The camera shows only me. It does not show the whole night.\"")],
        openings: ("A contractor's truck toolboxes were pried open at a job site and $1,900 in tools disappeared. A neighbor's camera shows {D} beside the truck at dusk, and a deputy found a flat bar in {DL}'s car that fits the marks.", "The defense will present a person who stopped to look at a house under construction, touched nothing, and keeps a flat bar for tires. Standing near a truck is not breaking into one."),
        closings: ("The camera puts {D} at the truck at dusk, and the flat bar in {D.his} car fits the marks. {D} had been in this court before.", "A neighbor's camera shows {D} standing by a truck, not opening it. A flat bar in a car is not a burglary tool, and the State has not proved who opened those boxes."),
        timeline: [(0, "Dusk: a neighbor's camera shows {D} beside the truck at the job site."), (1, "{V} finds the toolboxes pried open and $1,900 in tools gone."), (2, "A deputy finds a flat bar in {DL}'s car that fits the pry marks.")],
        identified: "A neighbor's camera.",
        mood: .wantsConviction)

    static let waistbandGunBack = SmallCases.make(
        key: "story.followup.waistbandGunBack",
        category: .violent,
        headlines: ["Handgun Seen in Waistband at Youth Football Game", "Defendant From Shooting Case Charged With Carrying a Concealed Weapon"],
        law: "concealedWeapon",
        spec: "Carried a concealed handgun about {D.his} person, on {DATE}.",
        ages: 19...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a school resource officer saw a handgun in {D}'s waistband when {DL} bent over at a youth football game on {DATE}. {DL} says {D.he} had a permit from another state.",
        state: [E(.physical, 3, "Handgun", "Loaded, recovered from the waistband."), E(.statement, 2, "School Resource Officer", "Saw the gun when {D} bent over.")],
        defense: [E(.statement, 1, "Out-of-State Permit", "{DL} says {D.he} had a permit.")],
        role: "School resource officer",
        exam: [.direct("What is your job?", "\"I am a school resource officer, and I work games and events at the high school and the youth fields.\""),
               .direct("What happened at the youth football game?", "\"I was walking the sideline when {DL} bent over to pick something up. I saw the grip of a handgun in {D.his} waistband.\""),
               .direct("Was it visible before that?", "\"No, it was under a jacket. It showed only when {DL} bent over.\""),
               .direct("What did you do?", "\"I approached, asked {DL} to stand, and secured the gun. It was loaded, and I recovered it from the waistband.\""),
               .direct("What did {DL} say?", "\"{D.He} said {D.he} had a permit from another state. I asked to see it.\""),
               .direct("What did the permit show?", "\"It was from another state. I looked it up, and it was not valid in this state, or at least it was not clear.\""),
               .direct("Why does that matter at a youth game?", "\"There were children all around, and a school-related event. A hidden gun in a crowd of children is a real risk.\""),
               .cross("Was the permit expired?", "\"I was told later that it had expired a month earlier. I did not check that at the field.\""),
               .cross("Was the gun ever drawn?", "\"No, it was never drawn and never touched until I took it. {DL} was cooperative the whole time, kept both hands in view, and did not argue with me about it.\""),
               .cross("Did {DL} try to hide it from you?", "\"No, {D.he} told me right away. {D.He} did not run or argue.\""),
               .cross("Was the permit from another state a valid one in that state?", "\"It was, in that state. I cannot say what it covered here.\""),
               .cross("You did not see the gun until {DL} bent over, did you?", "\"That is right. It was under the jacket the whole time.\"")],
        theory: ("{D} carried a concealed handgun at a youth football game.", "{D} held a permit from another state and forgot the gun was there."),
        allocution: "\"I didn't think, and I'm sorry. I'd forgotten the pistol was in my waistband when I bent over at that youth football game, and I thought my permit from another state covered me. I've been in this courtroom before, and I'll leave the gun home.\"",
        truths: ("{DL} had a prior case in this court and the permit had expired a month earlier.", "The permit was valid in the other state and {DL} had a note in the car."),
        defendant: [.direct("Were you armed that day?", "\"Yes, I had a pistol in my waistband. I had forgotten it was there.\""),
               .direct("Why did you have it?", "\"I carry it on the way home from work. I forgot to take it off before the game.\""),
               .direct("Did you have a permit?", "\"Yes, from another state. I thought it covered me here.\""),
               .direct("Did you know it had expired?", "\"No, I did not know that it had lapsed. I thought it was valid.\""),
               .direct("What did you do when the officer approached?", "\"I told the officer right away and handed it over. I did not argue.\""),
               .direct("What would you do differently?", "\"I would leave the gun at home. I should never have gone to a children's game with it.\""),
               .cross("The gun was under your jacket, wasn't it?", "\"Yes, it was under my jacket, and I did not take it out or show it to anyone at the game. I had simply forgotten it was on me.\""),
               .cross("You bent over, and it showed, didn't it?", "\"Yes, I bent over to pick up something I dropped, and the jacket rode up. That is how the officer saw the grip, and I told the officer right away.\""),
               .cross("You were in this court before, in {PRIORDATE}, weren't you?", "\"Yes, I was, and I should have been much more careful than I was.\""),
               .cross("You knew the permit was from another state, correct?", "\"Yes, I did, and I did not check the rules here.\""),
               .cross("A permit from another state is not a permit here, is it?", "\"I understand that now, after talking to the officer and reading about it. I did not understand it then, and I thought that permit covered me in this state too.\"")],
        openings: ("A school resource officer saw a loaded handgun in {D}'s waistband when {D.he} bent over at a youth football game. {D} had it concealed under a jacket and showed only a permit from another state, and {D} had been in this court before.", "The defense will present a permit holder who forgot the pistol was on {D.him}, told the officer at once, and handed it over without argument. A permit from another state, held in good faith, matters here."),
        closings: ("A loaded gun, hidden under a jacket, at a children's game. {D} had no permit that covers this state, and {D.he} was in this court before.", "{D} told the officer about the gun, handed it over, and held a permit from another state. The State has not shown that {D} meant to carry it concealed in violation of the law."),
        timeline: [(0, "{D} attends a youth football game with a handgun under a jacket."), (0, "{D} bends over, and a school resource officer sees the gun in {D.his} waistband."), (0, "The officer recovers the loaded handgun and checks the out-of-state permit.")],
        identified: "The officer's observation.",
        mood: .indifferent)

    static let gradePortalBack = SmallCases.make(
        key: "story.followup.gradePortalBack",
        category: .cyber,
        headlines: ["Student Portal Altered After Account Login From Home Network", "Defendant From Messaging Case Charged With Accessing a Computer"],
        law: "accessingComputers",
        spec: "Willfully and without authorization accessed a computer belonging to {V}, a school, on {DATE}.",
        ages: 18...30,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s student portal logged in to a teacher's account on {DATE} and changed three grades. The login came from {D}'s home network. {DL} says a roommate used the connection.",
        state: [E(.digital, 3, "Access Log", "Login from {D}'s home network."), E(.document, 2, "Grade History", "Three grades changed that night.")],
        defense: [E(.statement, 1, "Roommate", "{DL} says a roommate had the password.")],
        role: "School IT administrator",
        exam: [.direct("What is your role at the school?", "\"I am the IT administrator. I manage the student portal and the teacher accounts, and I review access logs.\""),
               .direct("What was changed?", "\"Three grades in a teacher's account. They were changed the night before the teacher noticed.\""),
               .direct("How did you find out?", "\"The teacher told me the grades did not match her records. I pulled the history and found the changes.\""),
               .direct("What did the access log show?", "\"A login to the teacher's account from an address that traces to {D}'s home network. The login happened that night.\""),
               .direct("What did the grade history show?", "\"The three grades were changed in a single session. The times line up with the login.\""),
               .direct("Did anyone else use that network?", "\"I cannot say. The log shows only the address of the router that made the connection, not which device or which person was using it that night.\""),
               .direct("What did you do next?", "\"I reset the teacher's password, preserved the log, and reported it to the school and the sheriff.\""),
               .cross("Could someone else use {DL}'s home network?", "\"Yes, it is possible, if they knew the Wi-Fi password.\""),
               .cross("Does the log show who typed the password?", "\"No, it does not. It records the address, the time, and the account, but nothing in it identifies the person who sat at the keyboard.\""),
               .cross("Was the teacher's password strong?", "\"It was an ordinary password. Someone could have guessed it.\""),
               .cross("Is it possible the teacher's login was shared?", "\"I cannot rule that out. Teachers sometimes give passwords to assistants or write them down, and I have no record showing who else knew this one.\""),
               .cross("You cannot say who was sitting at the computer, can you?", "\"No, I cannot say that. All I can tell the jury is which address the login came from and when, and that those match {DL}'s home network.\"")],
        theory: ("{D} used a teacher's account to change three grades from a home network.", "A roommate with the Wi-Fi password was the one who changed the grades."),
        allocution: "\"I should not have touched it, and I'm sorry. A roommate used my connection that night, and I never changed any grades. I've been in this courtroom before about a login, and I know it points to me. I'll change my password and stay off the portal.\"",
        truths: ("{DL} had a prior case in this court and two of the changed grades were {DL}'s own.", "The roommate admitted knowing the Wi-Fi password but not the teacher's login."),
        defendant: [.direct("Did you log in to the teacher's account?", "\"No, I did not. I never knew the teacher's password.\""),
               .direct("Do you have a roommate?", "\"Yes, I share an apartment. My roommate has the Wi-Fi password.\""),
               .direct("Where were you that night?", "\"I was at home. I was studying, and I went to bed early.\""),
               .direct("Are you a student at the school?", "\"Yes. I am told that some of the changed grades were mine, which would be a strange thing to do on my own network.\""),
               .direct("What do you think happened?", "\"I think someone used my connection. I do not know who.\""),
               .direct("What would you like the court to know?", "\"I did not change any grades. I would not risk my own record.\""),
               .cross("The login came from your home network, didn't it?", "\"Yes, I understand it did, and I have told the investigators the same. But that is the connection my roommate and I both use, and I was not the one at the computer.\""),
               .cross("Only you and your roommate had the password, correct?", "\"Yes, I think so. We gave it to a couple of friends once, but I do not remember who, and nobody was over that night as far as I know.\""),
               .cross("You were in this court before, in {PRIORDATE}, over a login, weren't you?", "\"Yes, I was, and I know how that looks to anyone hearing this. I learned a lot from that case, which is why I would not do it again.\""),
               .cross("Did you ask your roommate about it?", "\"I did, and my roommate did not give me a clear answer.\""),
               .cross("You do not have proof the roommate did it, do you?", "\"No, I do not have proof, and I will not say I do. I am only telling you that I did not do it and that someone else had the same access I did.\"")],
        openings: ("A teacher's portal account was logged into one night, and three grades were changed. The access log traces the login to {D}'s home network, and {DL} was in this court before over a login.", "The defense will present a student whose home network was shared with a roommate. An address on a log is a router, not a person, and the State has not shown who sat at the keyboard."),
        closings: ("The log points to {D}'s home network, the grades changed in one session, and {D} had been here before for a login.", "A network address is not a person. A roommate knew the Wi-Fi password, and the State has no proof of who was logged in."),
        timeline: [(0, "Night: someone logs in to a teacher's portal account from {D}'s home network."), (1, "The teacher notices three grades do not match the records."), (2, "The school IT administrator pulls the access log and grade history.")],
        identified: "The access log.",
        mood: .indifferent)

    static let boatRampDwiBack = SmallCases.make(
        key: "story.followup.boatRampDwiBack",
        category: .traffic,
        headlines: ["Driver Found Asleep in Running Truck at Boat Ramp", "Defendant From Revoked License Case Charged With Impaired Driving"],
        law: "dwi",
        spec: "Operated a motor vehicle on a public road while impaired, on {DATE}.",
        ages: 25...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a deputy found {D} slumped over the wheel of a running truck at a boat ramp on {DATE}. The truck was in gear with the brake on. A breath test read 0.12. {DL} says {D.he} was sleeping it off and never drove.",
        state: [E(.physical, 3, "Breath Test", "0.12 an hour after the stop."), E(.statement, 2, "Deputy", "Found {D} behind the wheel, engine running.")],
        defense: [E(.statement, 1, "Sleeping", "{DL} says {D.he} never left the lot.")],
        role: "Sheriff's deputy",
        exam: [.direct("What is your job?", "\"I am a sheriff's deputy. I patrol the county roads and the public boat ramps.\""),
               .direct("What did you find at the boat ramp that night?", "\"A pickup truck with the engine running, parked at the top of the ramp. {DL} was slumped over the wheel.\""),
               .direct("Was the truck moving?", "\"No. It was in gear with the brake on, so it was not moving, but it was ready to.\""),
               .direct("What did you do?", "\"I woke {DL} and asked for a license. {D.He} was slow to respond and smelled of alcohol.\""),
               .direct("What did the breath test show?", "\"0.12, about an hour after I made the stop. That is above the legal limit.\""),
               .direct("How did {DL} explain it?", "\"{D.He} said {D.he} was sleeping it off and had not driven. {D.He} said {D.he} had been drinking at the ramp.\""),
               .direct("What was in the truck?", "\"There was an open cooler with cans in it, and fishing gear in the bed.\""),
               .cross("Did you see the truck move?", "\"No, I did not see it move at any point. It was parked at the top of the ramp with the engine running when I arrived, and it stayed there until I woke {DL}.\""),
               .cross("Was {DL} asleep when you arrived?", "\"Yes, {D.he} was asleep behind the wheel with {D.his} head down, and it took me knocking on the window twice before {D.he} responded to me.\""),
               .cross("Was the engine running to keep warm?", "\"That is possible, and it was a cold night, so I will not rule it out. All I can say is that the engine was running and the truck was in gear.\""),
               .cross("Did you check for tire tracks?", "\"I looked, and there were tracks on the ramp road. I cannot say when they were made.\""),
               .cross("You cannot say when {DL} had last driven, can you?", "\"No, I cannot say when or where {DL} last drove. I did not see the truck on the road, and nobody told me anything about it.\"")],
        theory: ("{D} was in control of a running truck at a boat ramp while impaired.", "{D} was sleeping it off and never drove while drinking."),
        allocution: "\"I should have called for a ride, and I'm sorry. I was sleeping it off at that boat ramp, and I never drove that night. I've been in this courtroom before for drinking and driving, and I know that sitting behind the wheel looks bad. I'll accept the court's decision.\"",
        truths: ("{DL} had a prior case in this court and tire tracks on the boat ramp road matched the truck.", "A fishing buddy had called {DL} a ride but {DL} refused."),
        defendant: [.direct("Did you drive to the boat ramp?", "\"Yes, earlier in the evening, to fish. I was sober when I drove there.\""),
               .direct("When did you drink?", "\"After I got there. I had a cooler, and I drank for a couple of hours.\""),
               .direct("Why were you in the truck?", "\"I was cold and tired, and I was going to sleep it off. I started the engine for heat.\""),
               .direct("Why was it in gear?", "\"I put it in gear out of habit and kept my foot on the brake. I fell asleep that way.\""),
               .direct("Did you plan to drive?", "\"No. I had called a friend for a ride, but I did not want to wait.\""),
               .direct("What do you wish you had done?", "\"I wish I had called for a ride and gone home. I'm sorry I put everyone through this.\""),
               .cross("You were behind the wheel with the engine running, weren't you?", "\"Yes, I was, with my foot on the brake and the heater on. I was trying to stay warm and sleep, not to drive anywhere.\""),
               .cross("The breath test read 0.12, didn't it?", "\"Yes, it did, and I will not argue with the number. I had been drinking from the cooler for a couple of hours at that ramp.\""),
               .cross("You were in this court before, in {PRIORDATE}, for drinking and driving, weren't you?", "\"Yes, I was, and I know how it looks to sit behind the wheel again. That is why I stayed parked and did not go anywhere.\""),
               .cross("You drove to the ramp, didn't you?", "\"Yes, I drove there earlier in the evening, before I had anything to drink, so I could fish until dark. I did not drive after I started drinking.\""),
               .cross("A friend offered you a ride, and you refused, correct?", "\"Yes, I did, and I should have accepted it. I did not want to leave the truck and the gear at the ramp overnight, so I stayed.\"")],
        openings: ("A deputy found {D} slumped over the wheel of a running pickup at a boat ramp, in gear with the brake on. A breath test an hour later read 0.12, and {D} was in this court before over {PRIOR}.", "The defense will present a person who fished, drank at the ramp, and chose to sleep rather than drive. The truck never moved, and the State must show impaired operation on a road."),
        closings: ("The engine was running, the truck was in gear, and the breath test read 0.12. {D} was behind the wheel and had been here before.", "The truck never moved. {D} drank after parking and slept it off, and the State has not shown that {D} drove while impaired."),
        timeline: [(0, "Evening: {D} drives to the boat ramp to fish."), (0, "Night: a deputy finds {D} asleep behind the wheel of a running truck in gear."), (0, "A breath test an hour after the stop reads 0.12.")],
        identified: "The deputy's stop.",
        mood: .indifferent)
}
